// PreToolUse hook for Edit|Write: protects secrets, generated files and records that are not edited by hand.
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { ROOT, readInput, block, decide, relativeToRoot } = require('./lib.js');

/** [test(relPath), reason]. "deny" rules first, then "ask" rules. */
const DENY = [
  [
    (p) => /(^|\/)\.env(\.\w+)?$/.test(p) && !p.endsWith('.env.example'),
    'Agents never edit .env files (ADR 0018). Change .env.example and ask the owner.',
  ],
  [
    (p) => p.startsWith('apps/api/src/generated/'),
    'Generated by Prisma. Edit prisma/schema.prisma and run `pnpm --filter @skillboard/api db:generate`.',
  ],
  [
    (p) => p === 'apps/api/openapi.json' || p === 'packages/api-client/src/schema.ts',
    'Generated from the Nest app. Change the Zod schema / controller and run `pnpm api-client:generate`.',
  ],
  [
    (p) => p === 'pnpm-lock.yaml',
    'The lockfile is managed by pnpm. Use `pnpm add` / `pnpm remove` / `pnpm install`.',
  ],
  [
    (p) => /(^|\/)(node_modules|dist|\.next|\.turbo|coverage)\//.test(p),
    'Build output or dependencies; never edited by hand.',
  ],
];

const ASK = [
  [
    (p) => /^apps\/api\/prisma\/migrations\/.+\.sql$/.test(p) && fs.existsSync(path.join(ROOT, p)),
    'Editing an existing migration. Applied migrations must never change; only a migration created in this branch may be adjusted.',
  ],
  [
    (p) => /^docs\/decisions\/\d{4}-.+\.md$/.test(p) && fs.existsSync(path.join(ROOT, p)),
    'Editing an accepted ADR. The Decision section is immutable; add a new ADR that supersedes it instead (docs/decisions/README.md).',
  ],
  [
    (p) => p === '.claude/settings.json' || p.startsWith('.claude/hooks/'),
    'Changing the guard rails. Allowed, but the owner should know.',
  ],
];

const input = readInput();
const filePath = input.tool_input && input.tool_input.file_path;
const rel = relativeToRoot(filePath);
if (rel === null) process.exit(0);

for (const [test, reason] of DENY) {
  if (test(rel)) block(`Blocked edit of ${rel}: ${reason}`);
}
for (const [test, reason] of ASK) {
  if (test(rel)) decide('ask', `${rel}: ${reason}`);
}
process.exit(0);
